from taf.ul.bts_kpi_report_generator.converter.ErrorsHandlerToolsHolder import ErrorsHandlerToolsHolder


class WrongBracketsEnclosureError(ErrorsHandlerToolsHolder):
    """
    Class for handling wrong brackets enclosure error .
    """

    def __init__(self, source_file_path, release):
        ErrorsHandlerToolsHolder.__init__(self, source_file_path, release)

    def handle_wrong_brackets_enclosure_error(self, char, i, nested, kpi_id, xlsx_formula):
        """
        Checks for improper brackets enclosure, that is, check if
        amount of opened and closed brackets "[,]" in KPI's formula matches,
        if not, function tries to repair this kind of error .

        :param char: current examined char
        :param i: index of examined char
        :param nested: analyzed kpi's data
        :param kpi_id: analyzed kpi ID
        :param xlsx_formula: analyzed formula

        :return: None
        """
        formula_with_error = "{}\033[93m{}\033[00m{}".format(nested["FORMULA"][:i], char, nested["FORMULA"][i + 1:])
        self.ErrorsPrinter.warn_print("Wrong brackets enclosure", "{} : {}".format(kpi_id, formula_with_error))
        self.logger.warning("Wrong brackets enclosure {} : {}".format(kpi_id, nested["FORMULA"]))
        if not any("Wrong brackets enclosure" in error for error in self.found_errors):
            self.found_errors.append("Wrong brackets enclosure   (Amount of brackets '[', ']' opened and"
                                     " closed doesn't match, thus counter included in"
                                     " those brackets may not be translated"
                                     " into its value which may produce a NA value from the formula")

        # Repairing wrong brackets enclosure if possible
        first_non_space = self.first_non_blank_space(xlsx_formula[i - 1:0:-1])
        if nested["FORMULA"][i - 1 - first_non_space] == ']':
            xlsx_formula = "{} {}".format(
                xlsx_formula[:i + self.adjustment],
                xlsx_formula[i + 1 + self.adjustment:])
            self.ErrorsPrinter.info_print(
                "Attempt to repair the formula",
                "{} : {}{}{}{}{}".format(
                    kpi_id,
                    xlsx_formula[:i - 1 + self.adjustment - first_non_space],
                    self.colors["<gr>"],
                    xlsx_formula[i - 1 + self.adjustment - first_non_space],
                    self.colors["</gr>"],
                    xlsx_formula[i + self.adjustment - first_non_space:]
                ))
            self.logger.info("Attempt to repair the formula {} : {}".format(kpi_id, xlsx_formula))
        else:
            previous_closing_bracket = xlsx_formula[:i].rfind("]")
            for j in range(i, previous_closing_bracket, -1):
                if self.is_arithmetic(xlsx_formula[j]):
                    xlsx_formula = "{}[{}".format(
                        xlsx_formula[:j + 1 + self.first_non_blank_space(xlsx_formula[j + 1:])],
                        xlsx_formula[j + 1 + self.first_non_blank_space(xlsx_formula[j + 1:]):])
                    self.adjustment += 1
                    self.ErrorsPrinter.info_print("Attempt to repair the formula", "{} : {}{}{}{}{}".format(
                        kpi_id,
                        xlsx_formula[:j + 1 + self.first_non_blank_space(xlsx_formula[j + 1:])],
                        self.colors["<gr>"],
                        xlsx_formula[j + 1 + self.first_non_blank_space(xlsx_formula[j + 1:])],
                        self.colors["</gr>"],
                        xlsx_formula[j + 2 + self.first_non_blank_space(xlsx_formula[j + 1:]):]
                    ))
                    self.logger.info("Attempt to repair the formula {} : {}".format(kpi_id, xlsx_formula.replace(" ", "")))
                    break
        return xlsx_formula
